CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 160), created_at timestamptz NOT NULL DEFAULT now(), suspended boolean NOT NULL DEFAULT false);
CREATE TABLE memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), user_id uuid NOT NULL, role text NOT NULL CHECK(role IN ('owner','manager','caregiver','parent')), active boolean NOT NULL DEFAULT true, UNIQUE(organization_id,user_id));
CREATE TABLE platform_admins(user_id uuid PRIMARY KEY);
CREATE TABLE branches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Jakarta', UNIQUE(organization_id,id));
CREATE TABLE classrooms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), branch_id uuid NOT NULL, name text NOT NULL, UNIQUE(organization_id,id), FOREIGN KEY(organization_id,branch_id) REFERENCES branches(organization_id,id));
CREATE TABLE children(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), classroom_id uuid NOT NULL, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 160), birth_date date, archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), FOREIGN KEY(organization_id,classroom_id) REFERENCES classrooms(organization_id,id));
CREATE TABLE guardian_child_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), child_id uuid NOT NULL, user_id uuid NOT NULL, revoked_at timestamptz, UNIQUE(organization_id,child_id,user_id), FOREIGN KEY(organization_id,child_id) REFERENCES children(organization_id,id), FOREIGN KEY(organization_id,user_id) REFERENCES memberships(organization_id,user_id));
CREATE TABLE staff_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), child_id uuid NOT NULL, user_id uuid NOT NULL, revoked_at timestamptz, UNIQUE(organization_id,child_id,user_id), FOREIGN KEY(organization_id,child_id) REFERENCES children(organization_id,id), FOREIGN KEY(organization_id,user_id) REFERENCES memberships(organization_id,user_id));
CREATE TABLE invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), email text NOT NULL, role text NOT NULL CHECK(role IN ('manager','caregiver','parent')), child_id uuid, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, accepted_by uuid, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,child_id) REFERENCES children(organization_id,id));
-- Domain records use explicit kind constraints and per-kind JSON validation in the service.
-- Tenant and child FKs are relational, never accepted from a JSON payload.
CREATE TABLE records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), child_id uuid, kind text NOT NULL CHECK(kind IN ('settings','care-instruction','shift','attendance','pickup-authorization','pickup','activity','media','handoff','incident','incident-update','announcement','message','lead','lead-event','tour','trial','followup','enrollment','consent','data-request','camera-link','camera-policy','camera-session','analytics-ref','ai-query','ai-draft','fee-plan','invoice','payment','payment-event','subscription','usage','report','retention-job','job-run','support-access','integration-status')), data jsonb NOT NULL DEFAULT '{}', state text NOT NULL DEFAULT 'draft', created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), FOREIGN KEY(organization_id,child_id) REFERENCES children(organization_id,id));
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), actor_id uuid NOT NULL, action text NOT NULL, resource_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), user_id uuid NOT NULL, child_id uuid, event_key text NOT NULL, kind text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,user_id,event_key), FOREIGN KEY(organization_id,user_id) REFERENCES memberships(organization_id,user_id), FOREIGN KEY(organization_id,child_id) REFERENCES children(organization_id,id));
CREATE TABLE delivery_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), notification_id uuid NOT NULL REFERENCES notifications(id), channel text NOT NULL DEFAULT 'in-app', status text NOT NULL, attempted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE demo_leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, daycare text NOT NULL, contact text NOT NULL, data jsonb NOT NULL, fingerprint text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_keys(organization_id uuid NOT NULL REFERENCES organizations(id), user_id uuid NOT NULL, key text NOT NULL, request_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,user_id,key));
CREATE TABLE rate_limits(key text PRIMARY KEY, count integer NOT NULL, window_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX records_scope ON records(organization_id,kind,child_id,created_at DESC);
CREATE INDEX guardian_access ON guardian_child_links(user_id,child_id) WHERE revoked_at IS NULL;
CREATE INDEX staff_access ON staff_assignments(user_id,child_id) WHERE revoked_at IS NULL;
CREATE INDEX notifications_inbox ON notifications(organization_id,user_id,created_at DESC);
CREATE UNIQUE INDEX confirmed_tour_slot ON records(organization_id,(data->>'startsAt')) WHERE kind='tour' AND state='confirmed';
CREATE UNIQUE INDEX enrollment_once ON records(organization_id,(data->>'leadId')) WHERE kind='enrollment';
CREATE UNIQUE INDEX payment_once ON records(organization_id,(data->>'reference')) WHERE kind='payment';
CREATE FUNCTION app_user() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.user_id',true),'')::uuid $$;
CREATE FUNCTION app_org() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.organization_id',true),'')::uuid $$;
CREATE FUNCTION app_role() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT role FROM memberships m JOIN organizations o ON o.id=m.organization_id WHERE m.user_id=app_user() AND m.organization_id=app_org() AND m.active AND NOT o.suspended $$;
CREATE FUNCTION can_child(target uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM children c WHERE c.id=target AND c.organization_id=app_org() AND (app_role() IN ('owner','manager') OR (app_role()='parent' AND EXISTS(SELECT 1 FROM guardian_child_links g WHERE g.child_id=c.id AND g.organization_id=c.organization_id AND g.user_id=app_user() AND g.revoked_at IS NULL)) OR (app_role()='caregiver' AND EXISTS(SELECT 1 FROM staff_assignments s WHERE s.child_id=c.id AND s.organization_id=c.organization_id AND s.user_id=app_user() AND s.revoked_at IS NULL)))) $$;
CREATE FUNCTION can_record(k text, child uuid, s text, actor uuid, payload jsonb) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT app_role() IN ('owner','manager') OR (app_role()='caregiver' AND ((child IS NOT NULL AND can_child(child) AND k IN ('activity','attendance','media','pickup-authorization','pickup','care-instruction','incident','incident-update','message','ai-draft')) OR (k='handoff' AND (actor=app_user() OR payload->>'recipientId'=app_user()::text)) OR (k='shift' AND payload->>'userId'=app_user()::text))) OR (app_role()='parent' AND ((child IS NOT NULL AND can_child(child) AND ((k IN ('activity','media') AND s='published') OR k IN ('attendance','pickup-authorization','pickup','invoice') OR (k IN ('consent','data-request','message') AND actor=app_user()) OR (k='message' AND payload->>'recipientId'=app_user()::text))) OR (k='announcement' AND s='published'))) $$;
ALTER TABLE organizations ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_scope ON organizations USING(id=app_org() AND app_role() IS NOT NULL);
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY members_read ON memberships FOR SELECT USING(organization_id=app_org() AND (app_role() IN ('owner','manager') OR user_id=app_user()));
CREATE POLICY members_write ON memberships FOR UPDATE USING(organization_id=app_org() AND app_role()='owner') WITH CHECK(organization_id=app_org());
ALTER TABLE children ENABLE ROW LEVEL SECURITY;
CREATE POLICY children_read ON children FOR SELECT USING(organization_id=app_org() AND can_child(id));
CREATE POLICY children_create ON children FOR INSERT WITH CHECK(organization_id=app_org() AND app_role() IN ('owner','manager'));
CREATE POLICY children_update ON children FOR UPDATE USING(organization_id=app_org() AND app_role() IN ('owner','manager')) WITH CHECK(organization_id=app_org());
ALTER TABLE records ENABLE ROW LEVEL SECURITY;
CREATE POLICY records_read ON records FOR SELECT USING(organization_id=app_org() AND can_record(kind,child_id,state,created_by,data));
CREATE POLICY records_insert ON records FOR INSERT WITH CHECK(organization_id=app_org() AND created_by=app_user() AND (app_role() IN ('owner','manager') OR (app_role()='caregiver' AND ((child_id IS NOT NULL AND can_child(child_id) AND kind IN ('activity','attendance','media','incident','incident-update','message','ai-draft')) OR kind='handoff')) OR (app_role()='parent' AND child_id IS NOT NULL AND can_child(child_id) AND kind IN ('message','consent','data-request','pickup-authorization'))));
CREATE POLICY records_update ON records FOR UPDATE USING(organization_id=app_org() AND (app_role() IN ('owner','manager') OR (created_by=app_user() AND app_role()='caregiver' AND can_child(child_id) AND kind IN ('activity','media','ai-draft')) OR (app_role()='caregiver' AND kind='handoff' AND data->>'recipientId'=app_user()::text) OR (created_by=app_user() AND app_role()='parent' AND can_child(child_id) AND kind='consent'))) WITH CHECK(organization_id=app_org());
ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_read ON audit_logs FOR SELECT USING(organization_id=app_org() AND app_role() IN ('owner','manager'));
CREATE POLICY audit_insert ON audit_logs FOR INSERT WITH CHECK(organization_id=app_org() AND actor_id=app_user() AND app_role() IS NOT NULL);
CREATE FUNCTION immutable_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable history'; END $$;
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION immutable_audit();
ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notifications_read ON notifications FOR SELECT USING(organization_id=app_org() AND user_id=app_user() AND app_role() IS NOT NULL AND (child_id IS NULL OR can_child(child_id)));
CREATE POLICY notifications_update ON notifications FOR UPDATE USING(organization_id=app_org() AND user_id=app_user()) WITH CHECK(user_id=app_user());
-- Shared tenant configuration tables: parents can read room names, never membership tokens.
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['branches','classrooms','guardian_child_links','staff_assignments','invitations','idempotency_keys'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY scoped_read ON %I FOR SELECT USING(organization_id=app_org() AND app_role() IN (''owner'',''manager''))',t); END LOOP; END $$;
CREATE POLICY branch_names ON branches FOR SELECT USING(organization_id=app_org() AND app_role() IS NOT NULL);
CREATE POLICY classroom_names ON classrooms FOR SELECT USING(organization_id=app_org() AND app_role() IS NOT NULL);
CREATE POLICY branches_write ON branches FOR ALL USING(organization_id=app_org() AND app_role()='owner') WITH CHECK(organization_id=app_org() AND app_role()='owner');
CREATE POLICY classrooms_write ON classrooms FOR ALL USING(organization_id=app_org() AND app_role() IN ('owner','manager')) WITH CHECK(organization_id=app_org() AND app_role() IN ('owner','manager'));
-- API runtime must SET LOCAL ROLE daylio_app, not run as the migration owner.
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='daylio_app') THEN CREATE ROLE daylio_app NOLOGIN; END IF; END $$;
GRANT USAGE ON SCHEMA public TO daylio_app;
GRANT SELECT,INSERT,UPDATE ON organizations,memberships,branches,classrooms,children,records,guardian_child_links,staff_assignments,invitations,idempotency_keys,notifications TO daylio_app;
GRANT SELECT,INSERT ON audit_logs TO daylio_app;
GRANT EXECUTE ON FUNCTION app_user(),app_org(),app_role(),can_child(uuid),can_record(text,uuid,text,uuid,jsonb) TO daylio_app;
INSERT INTO schema_migrations(version) VALUES(1);
